import type { AuthResponseDto, LoginDto } from "@reactive-resume/dto";
import { useMutation } from "@tanstack/react-query";
import type { AxiosResponse } from "axios";
import { useNavigate } from "react-router";

import { axios, axiosForAuth } from "@/client/libs/axios";
import { queryClient } from "@/client/libs/query-client";
import { useAuthStore } from "@/client/stores/auth";

export const login = async (data: LoginDto) => {
  const response = await axiosForAuth.post<AuthResponseDto, AxiosResponse<AuthResponseDto>, LoginDto>(
    "/accounts/email-login/",
    data,
  );

  return response.data;
};

export const useLogin = () => {
  const navigate = useNavigate();
  const setUser = useAuthStore((state) => state.setUser);

  const {
    error,
    isPending: loading,
    mutateAsync: loginFn,
  } = useMutation({
    mutationFn: login,
    onSuccess: (data) => {
      console.log(data,"data 123123")
      localStorage.setItem("token", data.data.access);
      localStorage.setItem("refresh_token", data.data.refresh);
      localStorage.setItem("user", JSON.stringify(data.data.user));
      const user = data.data.user as any;
      console.log(user,"user")
      console.log(user.subscription_details.length,"ppppppppp")
      
      // Set user in auth store - this is critical for AuthGuard to work!
      setUser(data.data.user);
      
      if(user.role === "admin"){
        navigate("/admin")
        return
      }
      
      axios.get("/accounts/api/users/").then((res) => {
        localStorage.setItem("user",JSON.stringify(res.data[0]));
        // Update auth store with the fetched user data
        setUser(res.data[0]);
        navigate("/dashboard")
      })
      
      queryClient.setQueryData(["user"], data.data.user);
    },
  });

  return { login: loginFn, loading, error };
};
