import { axios } from '@/client/libs/axios';
import { useEffect, useState } from 'react';
import { useNavigate, useSearchParams } from 'react-router';

const SubscriptionStatus = () => {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const [status, setStatus] = useState<'loading' | 'success' | 'error'>('loading');
  const email = searchParams.get('email_id');
  const session_id=searchParams.get("session_id")
  const payment_type=searchParams.get("payment_type")
  const token=searchParams.get("token_id")
  const plan_id=searchParams.get("plan_id")
  const is_add_on_user=searchParams.get("add_on_user")

  console.log(session_id,"session_id")

  // http://localhost:5173/subscription-status?session_id=cs_test_a1ZLt9GzceqTS1IR6ehdpgE8TvLUJnFvu44jnwQB4zkX63rNh3yhSaXgWP&token_id=965a2f22-b6df-4354-a495-f1b4f617185b8ce5dd16-0e2a-4cfb-af9c-e58a5753527a2c88cf240-2791-48e6-a514-fbe92ecb6d89&plan_id=78ea7299-c069-4da7-955c-56d982aa6c2f&add_on_user=True

  useEffect(() => {
    const checkSubscriptionStatus = async () => {
      let API_URL=""
      if(is_add_on_user){
        API_URL=`/subscription/addon-user-payment/verify/`
      } else{
        API_URL=`/subscription/subscription/success/`
      }
      try {
        let response;
        response = await axios.get(`${API_URL}?token_id=${token}&session_id=${session_id}&plan_id=${plan_id}`);
        // if(payment_type=="one_time"){
        //      response = await axios.get(`/subscription/verify-one-time-payment/${session_id}/`);
        // }
        // else if(payment_type=="super_user"){
        //    response = await axios.get(`/subscription/session-status/${email}/${session_id}`);
        // }else{

        //   response = await axios.get(`/company/employees-subscription-status/${email}/${session_id}`);
        // }

        if (response.status === 200) {
          axios.get(`/accounts/api/users/`).then((res)=>{
            localStorage.setItem("user",JSON.stringify(res.data[0]))
    
          })
       
     

          setStatus('success');
          // Redirect to dashboard after 5 seconds
          setTimeout(() => {
            if(is_add_on_user){
              localStorage.setItem("is_add_on_user",JSON.stringify(true))
              navigate('/dashboard/account')
            } else{
              navigate('/dashboard');
            }
          }, 5000);
        } else {
          setStatus('error');
        }
      } catch (error) {
        setStatus('error');
      }
    };

    checkSubscriptionStatus();
  }, [email, navigate]);

  return (
    <div className="flex flex-col items-center justify-center min-h-screen gap-4">
      {status === 'loading' && (
        <>
          <h1 className="text-3xl font-bold mb-4">Checking Payment Status...</h1>
          <div className="w-10 h-10 border-4 border-blue-500 border-t-transparent rounded-full animate-spin" />
        </>
      )}
      
      {status === 'success' && (
        <>
          <h1 className="text-3xl font-bold mb-4 text-green-600">Payment Successful!</h1>
          <p className="text-gray-600 mb-4">
            Thank you for your subscription. You will be redirected to your dashboard shortly.
          </p>
          <div className="w-10 h-10 border-4 border-blue-500 border-t-transparent rounded-full animate-spin" />
        </>
      )}

      {status === 'error' && (
        <>
          <h1 className="text-3xl font-bold mb-4 text-red-600">Payment Not Successful</h1>
          <p className="text-gray-600 mb-4">
            There was an issue with your payment. Please try again or contact support.
          </p>
        </>
      )}
    </div>
  );
};

export default SubscriptionStatus;
