import { t } from "@lingui/macro";
import {
  CopySimple,
  FolderOpen,
  Lock,
  LockOpen,
  PencilSimple,
  TrashSimple,
  UserCheck,
} from "@phosphor-icons/react";
import type { ResumeDto } from "@reactive-resume/dto";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@reactive-resume/ui";
import { cn } from "@reactive-resume/utils";
import dayjs from "dayjs";
import { AnimatePresence, motion } from "framer-motion";
import { useNavigate } from "react-router";
import { useState } from "react";

import { useDialog } from "@/client/stores/dialog";
import { SubscriptionModal } from "@/client/components";

import { BaseCard } from "./base-card";

type Props = {
  resume: ResumeDto;
};

export const ResumeCard = ({ resume }: Props) => {
  const navigate = useNavigate();
  const { open } = useDialog<ResumeDto>("resume");
  const { open: lockOpen } = useDialog<ResumeDto>("lock");
  const [showSubscriptionModal, setShowSubscriptionModal] = useState(false);
  const [modalConfig, setModalConfig] = useState({ title: "", message: "" });

  const template = resume?.cv_template?.internal_name;
  const lastUpdated = dayjs().to(resume.updatedAt);
  const user = localStorage.getItem("user");
  const userData = JSON.parse(user || "{}");
  const hasSubscription = userData?.subscription_details?.length > 0;

  const showSubscriptionRequiredModal = (title: string, message: string) => {
    setModalConfig({ title, message });
    setShowSubscriptionModal(true);
  };

  const onOpen = () => {
    void navigate(`/builder/${resume.id}`);
  };

  const onUpdate = () => {
    open("update", { id: "resume", item: resume });
  };

  const onDuplicate = () => {
    if (userData.subscription_details.length === 0) {
      showSubscriptionRequiredModal(
        "Upgrade to Duplicate Resume",
        "Duplicating resumes requires a premium subscription. Upgrade now to create multiple versions of your resume!"
      );
      return;
    }
    open("duplicate", { id: "resume", item: resume });
  };

  const onLockChange = () => {
    if (userData.subscription_details.length === 0) {
      showSubscriptionRequiredModal(
        "Upgrade to Lock/Unlock Resume",
        "Locking and unlocking resumes requires a premium subscription. Upgrade now to protect your resume from accidental changes!"
      );
      return;
    }
    lockOpen(resume.locked ? "update" : "create", { id: "lock", item: resume });
  };

  const onDelete = () => {
    open("delete", { id: "resume", item: resume });
  };

  return (
    <>
      <DropdownMenu>
        <DropdownMenuTrigger className="text-left">
          <BaseCard className="cursor-context-menu space-y-0">
            <AnimatePresence>
              {resume.locked && (
                <motion.div
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  exit={{ opacity: 0 }}
                  className="absolute inset-0 flex items-center justify-center bg-background/75 backdrop-blur-sm"
                >
                  <Lock size={42} />
                </motion.div>
              )}
            </AnimatePresence>

            <div
              className={cn(
                "absolute inset-x-0 bottom-0 z-10 flex flex-col justify-end space-y-0.5 p-4 pt-12",
                "bg-gradient-to-t from-background/100 to-transparent",
              )}
            >
              <div className="flex items-center gap-2">
                <h4 className="line-clamp-2 font-medium flex-1">{resume.title}</h4>
                {resume.human_verification && (
                  <div className="flex items-center gap-1 bg-green-100 text-green-800 px-2 py-1 rounded-full text-xs font-medium flex-shrink-0">
                    <UserCheck size={10} />
                    <span className="hidden sm:inline">Human Verified</span>
                  </div>
                )}
              </div>
              <p className="line-clamp-1 text-xs opacity-75">{t`Last updated ${lastUpdated}`}</p>
            </div>

            <img
              src={`/templates/jpg/${template}.jpg`}
              alt={template}
              className="rounded-sm opacity-80"
            />
          </BaseCard>
        </DropdownMenuTrigger>

        <DropdownMenuContent>
          <DropdownMenuItem onClick={onOpen}>
            <FolderOpen size={14} className="mr-2" />
            {t`Open`}
          </DropdownMenuItem>
          <DropdownMenuItem onClick={onUpdate}>
            <PencilSimple size={14} className="mr-2" />
            {t`Rename`}
          </DropdownMenuItem>
          <DropdownMenuItem onClick={onDuplicate}>
            <CopySimple size={14} className="mr-2" />
            {t`Duplicate`}
          </DropdownMenuItem>
          {resume.locked ? (
            <DropdownMenuItem onClick={onLockChange}>
              <LockOpen size={14} className="mr-2" />
              {t`Unlock`}
            </DropdownMenuItem>
          ) : (
            <DropdownMenuItem onClick={onLockChange}>
              <Lock size={14} className="mr-2" />
              {t`Lock`}
            </DropdownMenuItem>
          )}
          <DropdownMenuSeparator />
          <DropdownMenuItem className="text-error" onClick={onDelete}>
            <TrashSimple size={14} className="mr-2" />
            {t`Delete`}
          </DropdownMenuItem>
        </DropdownMenuContent>
      </DropdownMenu>

      {/* Subscription Modal */}
      <SubscriptionModal
        isOpen={showSubscriptionModal}
        onClose={() => setShowSubscriptionModal(false)}
        title={modalConfig.title}
        message={modalConfig.message}
      />
    </>
  );
};
